from pathlib import Path

p = Path('index.html')
s = p.read_text()

# 1) Styles
old = '''  .rr-del svg{width:18px;height:18px;}\n  .btn-ghost.on{border-color:var(--clay);color:var(--clay-soft);}\n'''
new = '''  .rr-del svg{width:18px;height:18px;}\n  .routine-order-panel{margin-top:14px;padding-top:14px;border-top:1px solid var(--line);}\n  .routine-order-row{display:grid;grid-template-columns:34px minmax(0,1fr) 44px 44px;gap:7px;align-items:center;margin-bottom:7px;}\n  .routine-order-num{font-family:"Barlow Condensed";font-weight:700;font-size:17px;color:var(--dim);text-align:center;}\n  .routine-order-main{min-width:0;background:var(--bg2);border:1px solid var(--line2);border-radius:11px;padding:10px 11px;}\n  .routine-order-name{display:block;font-family:"Barlow Condensed";font-weight:700;font-size:17px;color:var(--cream);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n  .routine-order-sub{display:block;font-size:10.5px;color:var(--dim);text-transform:uppercase;letter-spacing:.8px;margin-top:1px;}\n  .routine-order-move{width:44px;height:44px;border-radius:11px;background:var(--surface2);color:var(--cream);border:1px solid var(--line2);font:700 21px/1 "Barlow",sans-serif;display:grid;place-items:center;}\n  .routine-order-move:active{transform:scale(.93);border-color:var(--clay);color:var(--clay-soft);}\n  .routine-order-move:disabled{opacity:.25;transform:none;}\n  .btn-ghost.on{border-color:var(--clay);color:var(--clay-soft);}\n'''
assert s.count(old) == 1, f'style anchor count {s.count(old)}'
s = s.replace(old, new, 1)

# 2) Inline panel on Session sheet
old = '''    <p class="seclabel">Templates</p>\n    <div id="routineList"></div>\n\n    <div class="divider"></div>\n'''
new = '''    <p class="seclabel">Templates</p>\n    <div id="routineList"></div>\n\n    <div class="routine-order-panel" id="routineOrderPanel" style="display:none">\n      <p class="seclabel" style="margin-bottom:5px">Order in current template</p>\n      <p class="muted" style="margin:0 0 10px">Move exercises up or down, then save. Logged reps on this day are kept.</p>\n      <div id="routineOrderList"></div>\n      <div class="btn-row">\n        <button class="btn btn-primary" id="saveRoutineOrder">Save order</button>\n      </div>\n    </div>\n\n    <div class="divider"></div>\n'''
assert s.count(old) == 1, f'panel anchor count {s.count(old)}'
s = s.replace(old, new, 1)

# 3) State
old = '''let editingIdx = null;                           // exercise being edited\n\nconst SB_URL ='''
new = '''let editingIdx = null;                           // exercise being edited\nlet routineOrderId = null;\nlet routineOrderDraft = null;\n\nconst SB_URL ='''
assert s.count(old) == 1, f'state anchor count {s.count(old)}'
s = s.replace(old, new, 1)

# 4) Add render/save functions immediately after renderRoutines
old = '''    row.appendChild(main); row.appendChild(del);\n    wrap.appendChild(row);\n  });\n}\n\n// ---- persistence: local-first; Supabase sync is asynchronous ----\n'''
new = '''    row.appendChild(main); row.appendChild(del);\n    wrap.appendChild(row);\n  });\n  renderRoutineOrder();\n}\n\nfunction renderRoutineOrder(){\n  const panel=el("routineOrderPanel"), list=el("routineOrderList");\n  if(!panel || !list) return;\n  const currentId=(DATA.workouts[cur]||{}).routineId || null;\n  const r=currentId ? routineById(currentId) : null;\n  if(!r || !Array.isArray(r.exercises) || !r.exercises.length){\n    panel.style.display="none"; list.innerHTML=""; routineOrderId=null; routineOrderDraft=null; return;\n  }\n  if(routineOrderId!==r.id || !Array.isArray(routineOrderDraft) || routineOrderDraft.length!==r.exercises.length){\n    routineOrderId=r.id;\n    routineOrderDraft=r.exercises.map((_,i)=>i);\n  }\n  panel.style.display="";\n  list.innerHTML="";\n  routineOrderDraft.forEach((originalIndex,pos)=>{\n    const ex=r.exercises[originalIndex];\n    const row=document.createElement("div"); row.className="routine-order-row";\n    const num=document.createElement("div"); num.className="routine-order-num"; num.textContent=String(pos+1);\n    const main=document.createElement("div"); main.className="routine-order-main";\n    const load=ex.bodyweight ? "BW" : ((ex.weight||0)+DATA.settings.units);\n    main.innerHTML=`<span class="routine-order-name">${escapeHtml(ex.name)}</span><span class="routine-order-sub">${ex.sets||5} × ${ex.targetReps||5} · ${escapeHtml(load)}</span>`;\n    const up=document.createElement("button"); up.type="button"; up.className="routine-order-move"; up.textContent="↑"; up.title="Move up"; up.disabled=pos===0;\n    const down=document.createElement("button"); down.type="button"; down.className="routine-order-move"; down.textContent="↓"; down.title="Move down"; down.disabled=pos===routineOrderDraft.length-1;\n    up.addEventListener("click",()=>{\n      if(pos<=0) return;\n      [routineOrderDraft[pos-1],routineOrderDraft[pos]]=[routineOrderDraft[pos],routineOrderDraft[pos-1]];\n      renderRoutineOrder();\n    });\n    down.addEventListener("click",()=>{\n      if(pos>=routineOrderDraft.length-1) return;\n      [routineOrderDraft[pos+1],routineOrderDraft[pos]]=[routineOrderDraft[pos],routineOrderDraft[pos+1]];\n      renderRoutineOrder();\n    });\n    row.append(num,main,up,down); list.appendChild(row);\n  });\n}\n\nfunction saveRoutineOrder(){\n  const r=routineById(routineOrderId);\n  if(!r || !Array.isArray(routineOrderDraft) || routineOrderDraft.length!==r.exercises.length) return;\n  const oldTemplate=r.exercises.slice();\n  const valid=routineOrderDraft.every(i=>Number.isInteger(i)&&i>=0&&i<oldTemplate.length) && new Set(routineOrderDraft).size===oldTemplate.length;\n  if(!valid){ toast("Could not save that order"); return; }\n  r.exercises=routineOrderDraft.map(i=>oldTemplate[i]);\n\n  // If this template is already on the current day, move the actual day\n  // exercise objects in the same way so any logged reps stay attached.\n  const wk=DATA.workouts[cur];\n  if(wk && wk.routineId===r.id){\n    const oldDay=wk.exercises.slice();\n    if(oldDay.length===oldTemplate.length){\n      wk.exercises=routineOrderDraft.map(i=>oldDay[i]);\n    } else {\n      // Best effort for a day that has been manually altered: match template\n      // names, preserve each matched exercise object, then keep extras at end.\n      const pool=oldDay.slice(), ordered=[];\n      r.exercises.forEach(t=>{\n        const i=pool.findIndex(x=>x.name===t.name);\n        if(i>=0) ordered.push(pool.splice(i,1)[0]);\n      });\n      wk.exercises=ordered.concat(pool);\n    }\n  }\n  routineOrderDraft=r.exercises.map((_,i)=>i);\n  save("reorder template "+r.name);\n  render(); renderRoutines();\n  toast("Saved "+r.name+" order");\n}\n\n// ---- persistence: local-first; Supabase sync is asynchronous ----\n'''
assert s.count(old) == 1, f'function anchor count {s.count(old)}'
s = s.replace(old, new, 1)

# 5) Reset draft whenever opening the Session sheet and wire save button
old = '''// session / templates\nel("wkLabel").onclick=()=>{ el("labelInput").value=ensureDay(cur).label; el("newTemplateName").value=""; renderRoutines(); open("ovSession"); };\nel("labelSave").onclick=()=>{ ensureDay(cur).label=(el("labelInput").value||"Workout").trim(); save("rename"); render(); toast("Renamed this day"); };\nel("saveAsTemplate").onclick=saveDayAsTemplate;\nel("closeSession").onclick=closeAll;\n'''
new = '''// session / templates\nel("wkLabel").onclick=()=>{\n  el("labelInput").value=ensureDay(cur).label; el("newTemplateName").value="";\n  routineOrderId=null; routineOrderDraft=null;\n  renderRoutines(); open("ovSession");\n};\nel("labelSave").onclick=()=>{ ensureDay(cur).label=(el("labelInput").value||"Workout").trim(); save("rename"); render(); toast("Renamed this day"); };\nel("saveAsTemplate").onclick=saveDayAsTemplate;\nel("saveRoutineOrder").onclick=saveRoutineOrder;\nel("closeSession").onclick=closeAll;\n'''
assert s.count(old) == 1, f'event anchor count {s.count(old)}'
s = s.replace(old, new, 1)

p.write_text(s)
print('Added current-template exercise reordering')
